import Button from '@jetbrains/ring-ui-built/components/button/button'
import {ControlsHeight} from '@jetbrains/ring-ui-built/components/global/controls-height'
import Link from '@jetbrains/ring-ui-built/components/link/link'
import {SvgIcon} from '@jetbrains/teamcity-ui/dist/components'
import {skipToken} from '@reduxjs/toolkit/query'
import classNames from 'classnames'
import {useMemo} from 'react'
import {EntryPointContainer} from 'react-relay'
import type {PreloadedEntryPoint} from 'react-relay/relay-hooks/EntryPointTypes'
import {useHref, useLinkClickHandler} from 'react-router'

import {EntityProvider} from '../../../contexts/entity'
import {usePermission} from '../../../hooks/usePermission'
import {sidebarArg} from '../../../rest/projects'
import {getCreateProjectHref} from '../../../routes'
import {restApi} from '../../../services/rest'
import {Permission, ROOT_PROJECT_ID, SakuraUIEnabledEnum} from '../../../types'
import {internalProps} from '../../../types/BS_types'
import version from '../../../utils/version'
import {feedbackHref, whatsNewHref} from '../../App/Header/HeaderTrayHelp/HeaderTrayHelp.consts'
import Loader from '../../common/Loader/Loader'
import UIPlaceholder from '../../common/UIPlaceholder/UIPlaceholder'
import {isCreateProjectNewUiEnabled} from '../PipelinesPages/utils/featureToggles'

import type {Props} from './FavoriteProjectsPage.types'

import styles from './FavoriteProjectsPage.module.css'

const leftTipText =
  'Choose and create projects or\u00A0build\u00A0configurations. For\u00A0quick access add them to your favorites.'

function FavoriteProjectsPage({
  hasProjects,
  hasFavoriteProjects,
  projectsLoaded,
  canShowAllProjects,
  entryPoint,
}: Props) {
  const hasPermissionToCreate = usePermission(Permission.EDIT_PROJECT, ROOT_PROJECT_ID)
  restApi.endpoints.getAllProjectsNormalized.useQuerySubscription(
    hasFavoriteProjects || projectsLoaded ? skipToken : sidebarArg,
  )
  const to = getCreateProjectHref(ROOT_PROJECT_ID)
  const href = useHref(to)
  const onClick = useLinkClickHandler(to)

  const renderProjectPageOuterContainer = useMemo(
    () => (
      <EntityProvider projectId={ROOT_PROJECT_ID}>
        <EntryPointContainer
          entryPointReference={entryPoint as PreloadedEntryPoint<any>}
          props={{}}
        />
      </EntityProvider>
    ),
    [entryPoint],
  )

  if (hasFavoriteProjects == null || (!hasFavoriteProjects && !projectsLoaded)) {
    return <Loader />
  } else if (hasFavoriteProjects || (hasProjects && canShowAllProjects)) {
    return renderProjectPageOuterContainer
  }

  const uiProp = internalProps['teamcity.ui.experimental']
  const isDefaultUI = [
    SakuraUIEnabledEnum.ENABLE_DEFAULT,
    SakuraUIEnabledEnum.ENABLE_ALL,
    SakuraUIEnabledEnum.ENABLE_ALL_SOFT,
  ].includes(uiProp)
  const customTitle = internalProps['teamcity.ui.customWelcomeTitle']
  const title =
    customTitle != null && customTitle.length > 0
      ? customTitle
      : isDefaultUI
        ? 'Welcome to TeamCity'
        : 'Welcome to TeamCity Sakura UI'

  return (
    <div className={styles.overviewPlaceholder}>
      {hasProjects && (
        <div className={classNames(styles.tip, styles.tipLeft)}>
          <SvgIcon icon="arrow-line-left" className={styles.arrow} />
          {leftTipText}
        </div>
      )}
      <UIPlaceholder title={title}>
        <div className={styles.linksContainer}>
          {hasPermissionToCreate &&
            (isCreateProjectNewUiEnabled ? (
              <Button
                height={ControlsHeight.M}
                data-test="create-project"
                className={styles.button}
                href={href}
                rel="noreferrer"
                onClick={onClick}
                primary
              >
                {'Create project...'}
              </Button>
            ) : (
              <Button
                href={to}
                className={styles.button}
                rel="noreferrer"
                data-test="create-project"
                primary
                height={ControlsHeight.M}
              >
                {'Create project...'}
              </Button>
            ))}
          <Link href={whatsNewHref} className={styles.link} target="_blank" rel="noreferrer">
            {`What's new in ${version.full}`}
          </Link>
          <Link href={feedbackHref} className={styles.link} target="_blank" rel="noreferrer">
            {'Send feedback...'}
          </Link>
        </div>
      </UIPlaceholder>
    </div>
  )
}

export default FavoriteProjectsPage
