import Theme from '@jetbrains/ring-ui-built/components/global/theme'
import {H1} from '@jetbrains/ring-ui-built/components/heading/heading'
import classNames from 'classnames'
import * as React from 'react'

import {useDarkOrLightTheme} from '../../../hooks/theme/useDarkOrLightTheme'
import {useSandbox} from '../../../utils/fastdom'

import welcomeToTeamCityDark from './Welcome to TeamCity - dark.svg'
import welcomeToTeamCityLight from './Welcome to TeamCity - light.svg'

import styles from './UIPlaceholder.module.css'

type Props = {
  infoContainerClassName?: string
  children?: React.ReactNode
  title: string
}
const BOTTOM_GAP = 150

function UIPlaceholder({children, title, infoContainerClassName}: Props) {
  const [availableHeight, setAvailableHeight] = React.useState<number | undefined>()
  const sandbox = useSandbox()
  React.useEffect(() => {
    const main = document.getElementById('main-content-tag')

    const updateHeight = () => {
      if (main) {
        sandbox.measure(() => {
          const clientRect = main.getBoundingClientRect()
          setAvailableHeight(clientRect.height - BOTTOM_GAP)
        })
      }
    }

    updateHeight()
    window.addEventListener('resize', updateHeight)
    return () => {
      window.removeEventListener('resize', updateHeight)
    }
  }, [sandbox])
  const theme = useDarkOrLightTheme()

  if (availableHeight == null && !IS_STORYBOOK) {
    return null
  }

  return (
    <div
      className={styles.wrapper}
      style={{
        minHeight: availableHeight,
      }}
    >
      <div className={classNames(styles.svgContainer, styles.defaultUi)}>
        <img
          alt="Welcome to TeamCity"
          src={theme === Theme.DARK ? welcomeToTeamCityDark : welcomeToTeamCityLight}
          /* eslint-disable @typescript-eslint/no-magic-numbers */
          width={theme === Theme.DARK ? 491 : 480}
          height={320}
          /* eslint-enable */
        />
      </div>
      <div className={classNames(styles.infoContainer, infoContainerClassName)}>
        <H1>{title}</H1>
        {children}
      </div>
    </div>
  )
}

export default UIPlaceholder
